#include <stddef.h>
#include <stdint.h>
#define BAD -1e300
double p2_quantile_estimator(const int64_t*v,size_t n){if(!v||n<2||n>65||v[0]<1||v[0]>64||n!=(size_t)v[0]+1)return BAD;size_t count=(size_t)v[0];double q[5]={0},np[5]={0,0.25,0.5,0.75,1},p[5]={0},d[5]={0};size_t seen=0;for(size_t z=0;z<count;z++){if(v[z+1]<INT32_MIN||v[z+1]>INT32_MAX)return BAD;double x=(double)v[z+1];if(seen<5){q[seen++]=x;if(seen==5){for(int a=1;a<5;a++){double t=q[a];int b=a;while(b>0&&q[b-1]>t){q[b]=q[b-1];b--;}q[b]=t;}for(int i=0;i<5;i++){p[i]=i+1;d[i]=i+1;}}continue;}int k;if(x<q[0]){q[0]=x;k=0;}else{k=3;for(int i=1;i<4;i++)if(x<q[i]){k=i-1;break;}if(x>q[4])q[4]=x;}for(int i=k+1;i<5;i++)p[i]++;for(int i=0;i<5;i++)d[i]+=np[i];for(int i=1;i<4;i++){double drift=d[i]-p[i];int right=drift>=1&&p[i+1]-p[i]>1,left=drift<=-1&&p[i-1]-p[i]<-1;if(!right&&!left)continue;int dir=right?1:-1;double l=p[i]-p[i-1],r=p[i+1]-p[i];double cand=q[i]+dir/(l+r)*((l+dir)*(q[i+1]-q[i])/r+(r-dir)*(q[i]-q[i-1])/l);if(q[i-1]<cand&&cand<q[i+1])q[i]=cand;else{int nb=i+dir;q[i]+=dir*(q[nb]-q[i])/(p[nb]-p[i]);}p[i]+=dir;}}if(seen<5){for(size_t a=1;a<count;a++){double x=q[a];size_t b=a;while(b>0&&q[b-1]>x){q[b]=q[b-1];b--;}q[b]=x;}double rank=.5*(count-1);size_t lo=(size_t)rank,hi=lo+1<count?lo+1:lo;return q[lo]+(rank-lo)*(q[hi]-q[lo]);}return q[2];}
